const fs = require('fs');
const path = require('path');
const { spawn, execFileSync } = require('child_process');

const BUILD_AGENT_DEFINITIONS = [
  { id: 'handoff', name: 'Generate handoff package', command: null, launch: 'handoff' },
  { id: 'cursor', name: 'Cursor', command: 'cursor', launch: 'open-project' },
  { id: 'claude', name: 'Claude Code', command: 'claude', launch: 'run-prompt' },
  { id: 'codex', name: 'Codex', command: 'codex', launch: 'run-prompt' },
  { id: 'hermes', name: 'Hermes', command: 'hermes', launch: 'run-prompt' },
  { id: 'opencode', name: 'OpenCode', command: 'opencode', launch: 'run-prompt' },
];

// Performance optimization: Module-level cache for resolved CLI agent commands on PATH.
// Avoids executing 5 synchronous child process spawns (`which`/`where`) on every call to `detectBuildAgents()`.
// Expected impact: ~17ms per call down to <0.01ms on cache hits (>1000x speedup), eliminating event loop blocking.
const COMMAND_PATH_CACHE = new Map();
const COMMAND_CACHE_TTL_MS = 10000;

function clearCommandCache() {
  COMMAND_PATH_CACHE.clear();
}

function findCommand(command) {
  if (!command) return null;
  const now = Date.now();
  const cached = COMMAND_PATH_CACHE.get(command);
  if (cached && now - cached.timestamp < COMMAND_CACHE_TTL_MS) {
    return cached.path;
  }

  const lookup = process.platform === 'win32' ? 'where' : 'which';
  let commandPath = null;
  try {
    commandPath =
      execFileSync(lookup, [command], { encoding: 'utf8' }).split(/\r?\n/).find(Boolean) || null;
  } catch {
    commandPath = null;
  }

  COMMAND_PATH_CACHE.set(command, { path: commandPath, timestamp: now });
  return commandPath;
}

function detectBuildAgents() {
  return BUILD_AGENT_DEFINITIONS.map((def) => {
    if (def.id === 'handoff') {
      return {
        id: def.id,
        name: def.name,
        available: true,
        command: null,
        launch: def.launch,
        notes: 'Always available',
      };
    }

    const commandPath = findCommand(def.command);
    return {
      id: def.id,
      name: def.name,
      available: Boolean(commandPath),
      command: commandPath,
      launch: def.launch,
      notes: commandPath ? 'Detected on PATH' : `${def.command} not found on PATH`,
    };
  });
}

function commandPreview(command, args) {
  return [command, ...args.map((arg) => (/\s/.test(arg) ? JSON.stringify(arg) : arg))].join(' ');
}

function launchBuildAgent({ agentId, projectPath, dryRun = false }) {
  const agents = detectBuildAgents();
  const agent = agents.find((item) => item.id === agentId) || agents[0];

  if (agent.id === 'handoff') {
    return { launched: false, fallback: false, agent, mode: 'handoff-only', command: null };
  }

  if (!agent.available || !agent.command) {
    return {
      launched: false,
      fallback: true,
      agent,
      mode: 'handoff-only',
      command: null,
      error: agent.notes,
    };
  }

  let args = [];
  let logPath = path.join(projectPath, 'build.log');

  if (agent.launch === 'open-project') {
    args = [projectPath];
  } else if (agent.launch === 'run-prompt') {
    const prompt = fs.readFileSync(path.join(projectPath, 'agent-prompt.md'), 'utf8');
    args = ['run', prompt, '--dir', projectPath];
  }

  const command = commandPreview(agent.command, args);
  if (dryRun) {
    return {
      launched: false,
      fallback: false,
      dryRun: true,
      agent,
      mode: 'dry-run',
      command,
      logPath,
    };
  }

  let outFd = null;
  try {
    outFd = fs.openSync(logPath, 'a');
    fs.appendFileSync(
      logPath,
      `\n\n=== Build agent launched ${new Date().toISOString()} ===\n${command}\n\n`
    );
    const child = spawn(agent.command, args, {
      cwd: projectPath,
      detached: true,
      stdio: ['ignore', outFd, outFd],
    });
    child.on('error', (err) => {
      fs.appendFileSync(logPath, `\nBuild agent failed to start: ${err.message}\n`);
    });
    child.unref();

    return {
      launched: true,
      fallback: false,
      agent,
      mode: 'launched',
      command,
      logPath,
      pid: child.pid,
    };
  } catch (err) {
    return {
      launched: false,
      fallback: true,
      agent,
      mode: 'handoff-only',
      command,
      logPath,
      error: `${agent.name} launch failed: ${err.message}`,
    };
  } finally {
    if (outFd !== null) fs.closeSync(outFd);
  }
}

module.exports = {
  BUILD_AGENT_DEFINITIONS,
  clearCommandCache,
  detectBuildAgents,
  launchBuildAgent,
};

const fs = require('fs');
const path = require('path');

function writeFile(projectPath, relativePath, content) {
  const filePath = path.join(projectPath, relativePath);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content, 'utf8');
  return relativePath;
}

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function stripHtmlDocument(html = '') {
  const bodyMatch = String(html || '').match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  return (bodyMatch?.[1] || html || '').trim();
}

function titleCase(value = '') {
  return String(value || 'Cauldron Project')
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

function defaultHtmlBody({ projectName, blueprint }) {
  const excerpt =
    String(blueprint || '')
      .replace(/[#*_`>-]/g, '')
      .trim()
      .slice(0, 420) ||
    'Generated from a Cauldron OS blueprint. Replace this starter content with the production implementation.';
  return `<main class="shell">
  <section class="hero">
    <p class="eyebrow">Cauldron scaffold</p>
    <h1>${escapeHtml(projectName)}</h1>
    <p>${escapeHtml(excerpt)}</p>
    <a href="#blueprint">Read the blueprint</a>
  </section>
  <section id="blueprint" class="panel">
    <h2>Build direction</h2>
    <p>Use <code>blueprint.md</code>, <code>design-system.md</code>, and <code>agent-prompt.md</code> as the source of truth.</p>
  </section>
</main>`;
}

function baseStyles() {
  return `:root {
  color-scheme: dark;
  --bg: #0d0f14;
  --panel: #171b23;
  --text: #f5f0e8;
  --muted: #aab0a6;
  --accent: #c1ff00;
  --line: rgba(255,255,255,0.12);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  color: var(--text);
  background: radial-gradient(circle at 20% 0%, rgba(193,255,0,0.12), transparent 30%), var(--bg);
}
a { color: var(--accent); }
.shell {
  width: min(1120px, calc(100vw - 32px));
  margin: 0 auto;
  padding: 72px 0;
}
.hero {
  display: grid;
  gap: 18px;
  padding: 48px;
  border: 1px solid var(--line);
  background: linear-gradient(135deg, rgba(255,255,255,0.07), rgba(255,255,255,0.025));
}
.eyebrow {
  margin: 0;
  color: var(--accent);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
h1 {
  margin: 0;
  font-size: clamp(42px, 8vw, 92px);
  line-height: 0.95;
}
h2 { margin-top: 0; }
p { max-width: 70ch; color: var(--muted); font-size: 18px; line-height: 1.55; }
.panel {
  margin-top: 24px;
  padding: 28px;
  border: 1px solid var(--line);
  background: var(--panel);
}
code { color: var(--accent); }
button, a {
  min-height: 44px;
}
`;
}

function scaffoldStaticHtml(context) {
  const body = stripHtmlDocument(context.prototypeHtml) || defaultHtmlBody(context);
  return [
    writeFile(
      context.projectPath,
      'index.html',
      `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${escapeHtml(context.projectName)}</title>
  <link rel="stylesheet" href="./styles.css" />
</head>
<body>
${body}
</body>
</html>
`
    ),
    writeFile(context.projectPath, 'styles.css', baseStyles()),
  ];
}

function scaffoldHtmlAlpine(context) {
  const body = stripHtmlDocument(context.prototypeHtml) || defaultHtmlBody(context);
  return [
    writeFile(
      context.projectPath,
      'index.html',
      `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${escapeHtml(context.projectName)}</title>
  <link rel="stylesheet" href="./styles.css" />
  <script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script>
  <script defer src="./app.js"></script>
</head>
<body x-data="cauldronScaffold()">
${body}
</body>
</html>
`
    ),
    writeFile(context.projectPath, 'styles.css', baseStyles()),
    writeFile(
      context.projectPath,
      'app.js',
      `function cauldronScaffold() {
  return {
    projectName: ${JSON.stringify(context.projectName)},
    generatedAt: ${JSON.stringify(new Date().toISOString())},
  };
}
`
    ),
  ];
}

function scaffoldNextjs(context) {
  const componentName = titleCase(context.projectName);
  const body = escapeHtml(
    stripHtmlDocument(context.prototypeHtml) ||
      'Build this page from blueprint.md and design-system.md.'
  );
  return [
    writeFile(
      context.projectPath,
      'package.json',
      JSON.stringify(
        {
          scripts: { dev: 'next dev', build: 'next build', start: 'next start' },
          dependencies: {
            '@types/node': 'latest',
            '@types/react': 'latest',
            '@types/react-dom': 'latest',
            next: 'latest',
            react: 'latest',
            'react-dom': 'latest',
            typescript: 'latest',
          },
          devDependencies: {},
        },
        null,
        2
      ) + '\n'
    ),
    writeFile(
      context.projectPath,
      'next.config.mjs',
      `const nextConfig = {};
export default nextConfig;
`
    ),
    writeFile(
      context.projectPath,
      'tsconfig.json',
      JSON.stringify(
        {
          compilerOptions: {
            target: 'es5',
            lib: ['dom', 'dom.iterable', 'esnext'],
            allowJs: true,
            skipLibCheck: true,
            strict: true,
            noEmit: true,
            esModuleInterop: true,
            module: 'esnext',
            moduleResolution: 'bundler',
            resolveJsonModule: true,
            isolatedModules: true,
            jsx: 'preserve',
            incremental: true,
          },
          include: ['next-env.d.ts', '**/*.ts', '**/*.tsx'],
          exclude: ['node_modules'],
        },
        null,
        2
      ) + '\n'
    ),
    writeFile(
      context.projectPath,
      'next-env.d.ts',
      '/// <reference types="next" />\n/// <reference types="next/image-types/global" />\n'
    ),
    writeFile(
      context.projectPath,
      'app/layout.tsx',
      `import './globals.css';

export const metadata = {
  title: ${JSON.stringify(context.projectName)},
  description: 'Generated by Cauldron OS',
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}
`
    ),
    writeFile(
      context.projectPath,
      'app/page.tsx',
      `export default function Page() {
  return (
    <main className="shell">
      <section className="hero">
        <p className="eyebrow">Cauldron scaffold</p>
        <h1>${componentName}</h1>
        <p>${body}</p>
        <a href="/blueprint.md">Read the blueprint</a>
      </section>
    </main>
  );
}
`
    ),
    writeFile(context.projectPath, 'app/globals.css', baseStyles()),
  ];
}

function scaffoldAstro(context) {
  const body = stripHtmlDocument(context.prototypeHtml) || defaultHtmlBody(context);
  return [
    writeFile(
      context.projectPath,
      'package.json',
      JSON.stringify(
        {
          scripts: { dev: 'astro dev', build: 'astro build', preview: 'astro preview' },
          dependencies: { astro: 'latest' },
          devDependencies: {},
        },
        null,
        2
      ) + '\n'
    ),
    writeFile(
      context.projectPath,
      'astro.config.mjs',
      `import { defineConfig } from 'astro/config';

export default defineConfig({});
`
    ),
    writeFile(
      context.projectPath,
      'src/pages/index.astro',
      `---
import '../styles/global.css';
const title = ${JSON.stringify(context.projectName)};
---
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{title}</title>
  </head>
  <body>
${body
  .split('\n')
  .map((line) => `    ${line}`)
  .join('\n')}
  </body>
</html>
`
    ),
    writeFile(context.projectPath, 'src/styles/global.css', baseStyles()),
  ];
}

const SCAFFOLDERS = {
  'static-html': scaffoldStaticHtml,
  'html-alpine': scaffoldHtmlAlpine,
  nextjs: scaffoldNextjs,
  astro: scaffoldAstro,
};

const SCAFFOLD_METADATA = {
  'static-html': {
    entrypoint: 'index.html',
    packageManager: null,
    commands: {},
    roles: { 'index.html': 'entry', 'styles.css': 'style' },
  },
  'html-alpine': {
    entrypoint: 'index.html',
    packageManager: null,
    commands: {},
    roles: { 'index.html': 'entry', 'styles.css': 'style', 'app.js': 'script' },
  },
  nextjs: {
    entrypoint: 'app/page.tsx',
    packageManager: 'npm',
    commands: { dev: 'npm run dev', build: 'npm run build', start: 'npm run start' },
    roles: {
      'package.json': 'manifest',
      'next.config.mjs': 'config',
      'tsconfig.json': 'config',
      'next-env.d.ts': 'types',
      'app/layout.tsx': 'layout',
      'app/page.tsx': 'entry',
      'app/globals.css': 'style',
    },
  },
  astro: {
    entrypoint: 'src/pages/index.astro',
    packageManager: 'npm',
    commands: { dev: 'npm run dev', build: 'npm run build', preview: 'npm run preview' },
    roles: {
      'package.json': 'manifest',
      'astro.config.mjs': 'config',
      'src/pages/index.astro': 'entry',
      'src/styles/global.css': 'style',
    },
  },
};

function fileMetadata(scaffoldId, relativePath) {
  const role = SCAFFOLD_METADATA[scaffoldId]?.roles?.[relativePath] || 'source';
  return {
    path: relativePath,
    role,
    kind: role === 'manifest' || role === 'config' ? 'config' : 'source',
    generated: true,
  };
}

function createScaffold(context) {
  const requestedId = context.templateId || 'html-alpine';
  const scaffoldId = SCAFFOLDERS[requestedId]
    ? requestedId
    : SCAFFOLDERS[context.projectType]
      ? context.projectType
      : 'html-alpine';
  const scaffold = SCAFFOLDERS[scaffoldId];
  const paths = scaffold(context);
  const metadata = SCAFFOLD_METADATA[scaffoldId] || SCAFFOLD_METADATA['html-alpine'];
  return {
    id: scaffoldId,
    templateId: scaffoldId,
    scaffold: scaffoldId,
    entrypoint: metadata.entrypoint,
    packageManager: metadata.packageManager,
    commands: metadata.commands,
    files: paths.map((file) => fileMetadata(scaffoldId, file)),
    paths,
  };
}

function npmExecutable(platform = process.platform) {
  return platform === 'win32' ? 'npm.cmd' : 'npm';
}

function npmSpawnOptions(projectPath, platform = process.platform) {
  return {
    cwd: projectPath,
    detached: true,
    stdio: 'ignore',
    shell: platform === 'win32',
  };
}

function bootstrapScaffold(projectPath, templateId) {
  const metadata = SCAFFOLD_METADATA[templateId] || SCAFFOLD_METADATA['html-alpine'];
  if (!metadata.packageManager) {
    return { bootstrapped: false, reason: 'No package manager for this template' };
  }
  const { spawn } = require('child_process');
  return new Promise((resolve) => {
    const child = spawn(npmExecutable(), ['install'], npmSpawnOptions(projectPath));
    child.on('error', (err) => {
      resolve({ bootstrapped: false, reason: err.message });
    });
    child.on('close', (code) => {
      resolve({ bootstrapped: code === 0, exitCode: code });
    });
    child.unref();
  });
}

module.exports = {
  createScaffold,
  SCAFFOLD_METADATA,
  SCAFFOLDERS,
  bootstrapScaffold,
  npmExecutable,
  npmSpawnOptions,
};

const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');
const { promisify } = require('util');
const { isInsideRoot } = require('./path-safety');
const { scorePrototypeHtml } = require('./quality-scorer');
const { SCAFFOLD_METADATA } = require('./scaffold-generator');

const execAsync = promisify(exec);
const PLACEHOLDER_PATTERN = /\b(lorem ipsum|placeholder|todo|replace me|coming soon)\b/i;
const LOCAL_ASSET_PATTERN = /(?:src|href)=["']([^"']+)["']/gi;

function normalizeCheckResult(check = {}) {
  return {
    id: check.id || 'unknown',
    label: check.label || check.id || 'Unknown check',
    category: check.category || 'static',
    status: check.status || 'skipped',
    command: check.command || null,
    stdout: check.stdout || '',
    stderr: check.stderr || '',
    exitCode: check.exitCode ?? null,
    durationMs: Number(check.durationMs || 0),
    details: check.details || null,
  };
}

function computeOverallResult(checks = []) {
  const normalized = checks.map(normalizeCheckResult);
  if (normalized.some((check) => check.status === 'failed')) return 'BLOCKED';
  if (normalized.some((check) => check.status === 'passed' || check.status === 'skipped')) {
    if (
      normalized.some((check) => check.status === 'skipped' || check.status === 'not_configured')
    ) {
      return 'PASS_WITH_WARNINGS';
    }
    const accessibilityCheck = normalized.find((check) => check.id === 'accessibility');
    if (
      accessibilityCheck?.details?.quality?.grade &&
      ['C', 'D'].includes(accessibilityCheck.details.quality.grade)
    ) {
      return 'PASS_WITH_WARNINGS';
    }
    return 'PASS';
  }
  return 'PASS_WITH_WARNINGS';
}

function safeResolve(targetDir, relativePath = '') {
  const root = path.resolve(targetDir);
  const resolved = path.resolve(root, relativePath);
  if (!isInsideRoot(root, resolved)) {
    throw new Error(`Verification path escaped target directory: ${relativePath}`);
  }
  return resolved;
}

function fileExists(filePath) {
  try {
    return fs.existsSync(filePath);
  } catch {
    return false;
  }
}

function readJsonIfExists(filePath) {
  if (!fileExists(filePath)) return null;
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function inferScaffold({ manifest = null, templateId = '' } = {}) {
  const manifestScaffold = manifest?.scaffold || null;
  if (manifestScaffold?.entrypoint) return manifestScaffold;

  const key = templateId && SCAFFOLD_METADATA[templateId] ? templateId : 'html-alpine';
  const metadata = SCAFFOLD_METADATA[key] || SCAFFOLD_METADATA['html-alpine'];
  return {
    id: key,
    templateId: key,
    entrypoint: metadata.entrypoint,
    packageManager: metadata.packageManager,
    commands: metadata.commands || {},
    files: Object.keys(metadata.roles || {}).map((filePath) => ({
      path: filePath,
      role: metadata.roles[filePath],
    })),
  };
}

function summarizeChecks(checks = []) {
  return checks.reduce(
    (summary, check) => {
      summary[check.status] = (summary[check.status] || 0) + 1;
      return summary;
    },
    {
      passed: 0,
      failed: 0,
      skipped: 0,
      not_configured: 0,
    }
  );
}

async function runCommand(command, cwd, timeoutMs = 60000) {
  const startedAt = Date.now();
  try {
    const { stdout, stderr } = await execAsync(command, {
      cwd,
      timeout: timeoutMs,
      maxBuffer: 10 * 1024 * 1024,
    });
    return {
      stdout: stdout || '',
      stderr: stderr || '',
      exitCode: 0,
      durationMs: Date.now() - startedAt,
    };
  } catch (error) {
    return {
      stdout: error.stdout || '',
      stderr: error.stderr || error.message || '',
      exitCode: typeof error.code === 'number' ? error.code : 1,
      durationMs: Date.now() - startedAt,
    };
  }
}

function collectLocalReferences(html = '') {
  const refs = [];
  for (const match of String(html).matchAll(LOCAL_ASSET_PATTERN)) {
    const ref = String(match[1] || '').trim();
    if (
      !ref ||
      ref.startsWith('http://') ||
      ref.startsWith('https://') ||
      ref.startsWith('mailto:') ||
      ref.startsWith('#') ||
      ref.startsWith('data:')
    ) {
      continue;
    }
    refs.push(ref.replace(/^\.\//, ''));
  }
  return Array.from(new Set(refs));
}

function buildManifestChecks({ targetDir, manifest, scaffold }) {
  const manifestPath = path.join(targetDir, 'cauldron.project.json');
  const checks = [];
  checks.push(
    normalizeCheckResult({
      id: 'manifest-file',
      label: 'Manifest file exists',
      category: 'manifest',
      status: fileExists(manifestPath) ? 'passed' : 'not_configured',
      details: { path: 'cauldron.project.json' },
    })
  );

  const entrypointPath = scaffold?.entrypoint ? safeResolve(targetDir, scaffold.entrypoint) : null;
  checks.push(
    normalizeCheckResult({
      id: 'entrypoint',
      label: 'Entrypoint exists',
      category: 'manifest',
      status: entrypointPath && fileExists(entrypointPath) ? 'passed' : 'failed',
      details: { entrypoint: scaffold?.entrypoint || null },
    })
  );

  const missingFiles = (scaffold?.files || [])
    .map((file) => file.path)
    .filter(Boolean)
    .filter((filePath) => !fileExists(safeResolve(targetDir, filePath)));

  checks.push(
    normalizeCheckResult({
      id: 'scaffold-files',
      label: 'Scaffold files present',
      category: 'manifest',
      status: missingFiles.length ? 'failed' : 'passed',
      details: { missingFiles },
    })
  );

  if (manifest) {
    checks.push(
      normalizeCheckResult({
        id: 'manifest-json',
        label: 'Manifest JSON parsed',
        category: 'manifest',
        status: 'passed',
        details: {
          templateId: manifest.templateId || scaffold?.templateId || null,
          source: manifest.source || null,
        },
      })
    );
  }

  return checks;
}

function buildStaticChecks({ targetDir, scaffold }) {
  const entrypoint = scaffold?.entrypoint ? safeResolve(targetDir, scaffold.entrypoint) : null;
  if (!entrypoint || !fileExists(entrypoint) || !entrypoint.endsWith('.html')) {
    return [
      normalizeCheckResult({
        id: 'static-refs',
        label: 'Local references resolve',
        category: 'static',
        status: 'not_configured',
      }),
      normalizeCheckResult({
        id: 'placeholder-copy',
        label: 'Placeholder copy removed',
        category: 'static',
        status: 'not_configured',
      }),
    ];
  }

  const html = fs.readFileSync(entrypoint, 'utf8');
  const refs = collectLocalReferences(html);
  const missingRefs = refs.filter((ref) => !fileExists(safeResolve(path.dirname(entrypoint), ref)));
  const hasHtmlShell = /<html[\s>]/i.test(html) && /<body[\s>]/i.test(html);
  const hasPlaceholderCopy = PLACEHOLDER_PATTERN.test(html);

  return [
    normalizeCheckResult({
      id: 'html-shell',
      label: 'HTML shell is present',
      category: 'static',
      status: hasHtmlShell ? 'passed' : 'failed',
      details: { entrypoint: scaffold.entrypoint },
    }),
    normalizeCheckResult({
      id: 'static-refs',
      label: 'Local references resolve',
      category: 'static',
      status: missingRefs.length ? 'failed' : 'passed',
      details: { missingRefs },
    }),
    normalizeCheckResult({
      id: 'placeholder-copy',
      label: 'Placeholder copy removed',
      category: 'static',
      status: hasPlaceholderCopy ? 'failed' : 'passed',
      details: hasPlaceholderCopy ? { pattern: PLACEHOLDER_PATTERN.source } : null,
    }),
  ];
}

function buildAccessibilityCheck({ targetDir, scaffold }) {
  const entrypoint = scaffold?.entrypoint ? safeResolve(targetDir, scaffold.entrypoint) : null;
  if (!entrypoint || !fileExists(entrypoint) || !entrypoint.endsWith('.html')) {
    return normalizeCheckResult({
      id: 'accessibility',
      label: 'Accessibility heuristics',
      category: 'accessibility',
      status: 'not_configured',
    });
  }

  const html = fs.readFileSync(entrypoint, 'utf8');
  const quality = scorePrototypeHtml(html);
  return normalizeCheckResult({
    id: 'accessibility',
    label: 'Accessibility heuristics',
    category: 'accessibility',
    status: quality.grade === 'D' ? 'failed' : quality.grade === 'C' ? 'skipped' : 'passed',
    details: { quality },
  });
}

async function buildCommandChecks({ targetDir, scaffold, options = {} }) {
  const packageJsonPath = path.join(targetDir, 'package.json');
  const packageJson = readJsonIfExists(packageJsonPath);
  const checks = [];
  const timeoutMs = Number(options.commandTimeoutMs || 60000);

  if (!scaffold?.packageManager || !packageJson) {
    checks.push(
      normalizeCheckResult({
        id: 'install-command',
        label: 'Install command',
        category: 'command',
        status: 'not_configured',
        details: { packageManager: scaffold?.packageManager || null },
      })
    );
  } else {
    const installCommand =
      scaffold.packageManager === 'npm' ? 'npm install' : `${scaffold.packageManager} install`;
    const installResult = await runCommand(installCommand, targetDir, timeoutMs);
    checks.push(
      normalizeCheckResult({
        id: 'install-command',
        label: 'Install command',
        category: 'command',
        status: installResult.exitCode === 0 ? 'passed' : 'failed',
        command: installCommand,
        ...installResult,
      })
    );
  }

  const commandDefinitions = [
    { id: 'build-command', label: 'Build command', command: scaffold?.commands?.build || null },
    {
      id: 'test-command',
      label: 'Test command',
      command: packageJson?.scripts?.test ? 'npm test' : null,
    },
  ];

  for (const definition of commandDefinitions) {
    if (!definition.command) {
      checks.push(
        normalizeCheckResult({
          id: definition.id,
          label: definition.label,
          category: 'command',
          status: 'not_configured',
        })
      );
      continue;
    }

    const result = await runCommand(definition.command, targetDir, timeoutMs);
    checks.push(
      normalizeCheckResult({
        id: definition.id,
        label: definition.label,
        category: 'command',
        status: result.exitCode === 0 ? 'passed' : 'failed',
        command: definition.command,
        ...result,
      })
    );
  }

  return checks;
}

async function runVerification({ targetDir, manifest = null, options = {} }) {
  if (!targetDir) {
    throw new Error('targetDir is required for verification');
  }

  const resolvedTargetDir = path.resolve(targetDir);
  if (!fileExists(resolvedTargetDir)) {
    throw new Error(`Verification target does not exist: ${resolvedTargetDir}`);
  }

  const existingManifest =
    manifest || readJsonIfExists(path.join(resolvedTargetDir, 'cauldron.project.json'));
  const scaffold = inferScaffold({
    manifest: existingManifest,
    templateId: options.templateId || existingManifest?.templateId || '',
  });

  const checks = [
    ...buildManifestChecks({ targetDir: resolvedTargetDir, manifest: existingManifest, scaffold }),
    ...buildStaticChecks({ targetDir: resolvedTargetDir, scaffold }),
    buildAccessibilityCheck({ targetDir: resolvedTargetDir, scaffold }),
    ...(await buildCommandChecks({ targetDir: resolvedTargetDir, scaffold, options })),
  ].map(normalizeCheckResult);

  return {
    targetDir: resolvedTargetDir,
    targetType: options.targetType || (existingManifest ? 'project' : 'workspace'),
    ranAt: new Date().toISOString(),
    scaffold: {
      id: scaffold.id || scaffold.templateId || options.templateId || null,
      entrypoint: scaffold.entrypoint || null,
      packageManager: scaffold.packageManager || null,
      commands: scaffold.commands || {},
    },
    overall: computeOverallResult(checks),
    summary: summarizeChecks(checks),
    checks,
  };
}

module.exports = {
  normalizeCheckResult,
  computeOverallResult,
  runVerification,
};

const CATEGORY_WEIGHTS = {
  accessibility: 0.22,
  visualHierarchy: 0.2,
  spacing: 0.18,
  colorContrast: 0.2,
  semanticHtml: 0.2,
};

// Performance optimization: Module-level static RegExp instances avoid repeated
// compilation and RegExp object instantiation inside scoring functions.
const RE_IMG = /<img\b/gi;
const RE_LABELLED_IMG = /<img\b[^>]*\salt\s*=/gi;
const RE_CONTROLS = /<(button|input|select|textarea|a)\b/gi;
const RE_LABELLED_CONTROLS =
  /<(button|input|select|textarea|a)\b[^>]*(aria-label|aria-labelledby|title|for=|type=)/gi;
const RE_LANG = /<html\b[^>]*\blang\s*=/i;
const RE_MAIN = /<main\b/i;
const RE_ARIA = /aria-|role=|for=|id=/;
const RE_FOCUS = /focus|:focus|tabindex/i;

const RE_H1 = /<h1\b/gi;
const RE_HEADINGS = /<h[1-6]\b/gi;
const RE_PARAGRAPHS = /<p\b/gi;
const RE_CTAS = /<(button|a)\b[^>]*(class|aria-label|href|type)/gi;
const RE_HIERARCHY_KEYWORDS = /hero|headline|eyebrow|kicker|cta|primary/i;
const RE_FONT_STYLING = /font-size|font-weight|line-height/i;

const RE_SPACING =
  /\b(padding|margin|gap|grid-template|display:\s*grid|display:\s*flex|max-width|width|min-height)\b/gi;
const RE_SECTIONS = /<(section|article|header|footer|aside)\b/gi;
const RE_LAYOUT_KEYWORDS = /container|wrapper|stack|grid|layout/i;
const RE_UNITS = /px|rem|clamp\(/i;

const RE_HEX_COLOR = /#[0-9a-f]{3}(?:[0-9a-f]{3})?\b/gi;
const RE_COLOR_BG = /color\s*:|background/i;
const RE_BORDER = /border|box-shadow|outline/i;

const RE_SEMANTIC_TAGS =
  /<(main|header|nav|section|article|aside|footer|form|label|figure|ul|ol|li)\b/gi;
const RE_DIVS = /<div\b/gi;
const RE_DOCTYPE = /<!doctype html>/i;
const RE_TITLE = /<title\b/i;
const RE_TYPED_BUTTON = /<button\b[^>]*\btype\s*=/i;

function clampScore(value) {
  return Math.max(0, Math.min(100, Math.round(value)));
}

/**
 * Counts pattern occurrences in text without allocating match arrays.
 * Performance optimization: Using pattern.test() in a loop with pattern.lastIndex = 0
 * avoids allocating intermediate Array instances and matched substring objects.
 */
function countMatches(text, pattern) {
  if (!text) return 0;
  if (pattern.global) {
    pattern.lastIndex = 0;
    let count = 0;
    while (pattern.test(text)) {
      count += 1;
    }
    return count;
  }
  return pattern.test(text) ? 1 : 0;
}

/**
 * Checks if non-tag text in HTML exceeds minLength without creating giant intermediate strings.
 * Performance optimization: avoids multi-pass global regex string replacements on entire HTML documents.
 * Exits immediately once minLength non-tag characters are counted (~500x speedup for large documents).
 */
function hasMinTextLength(html = '', minLength = 81) {
  let count = 0;
  let inTag = false;
  let hasPendingSpace = false;
  const str = String(html || '');
  const len = str.length;

  for (let i = 0; i < len; i += 1) {
    const ch = str[i];
    if (ch === '<') {
      inTag = true;
      hasPendingSpace = true;
    } else if (ch === '>') {
      inTag = false;
    } else if (!inTag) {
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
        hasPendingSpace = true;
      } else {
        if (count > 0 && hasPendingSpace) {
          count += 1;
        }
        hasPendingSpace = false;
        count += 1;
        if (count >= minLength) return true;
      }
    }
  }

  return count >= minLength;
}

function expandHex(hex) {
  const value = hex.replace('#', '');
  if (value.length === 3) {
    return value
      .split('')
      .map((char) => char + char)
      .join('');
  }
  return value;
}

function hexToRgb(hex) {
  const value = expandHex(hex);
  if (value.length !== 6) return null;
  const number = Number.parseInt(value, 16);
  if (Number.isNaN(number)) return null;
  return {
    r: (number >> 16) & 255,
    g: (number >> 8) & 255,
    b: number & 255,
  };
}

function luminanceChannel(value) {
  const normalized = value / 255;
  return normalized <= 0.03928 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
}

function relativeLuminance(rgb) {
  return (
    0.2126 * luminanceChannel(rgb.r) +
    0.7152 * luminanceChannel(rgb.g) +
    0.0722 * luminanceChannel(rgb.b)
  );
}

function contrastRatio(foreground, background) {
  const first = hexToRgb(foreground);
  const second = hexToRgb(background);
  if (!first || !second) return 0;
  const lighter = Math.max(relativeLuminance(first), relativeLuminance(second));
  const darker = Math.min(relativeLuminance(first), relativeLuminance(second));
  return (lighter + 0.05) / (darker + 0.05);
}

function scoreAccessibility(html, hasSubstantialText) {
  let score = 45;
  const imageCount = countMatches(html, RE_IMG);
  const labelledImages = countMatches(html, RE_LABELLED_IMG);
  const controls = countMatches(html, RE_CONTROLS);
  const labelledControls = countMatches(html, RE_LABELLED_CONTROLS);

  if (RE_LANG.test(html)) score += 12;
  if (RE_MAIN.test(html)) score += 8;
  if (RE_ARIA.test(html)) score += 12;
  if (RE_FOCUS.test(html)) score += 8;
  if (imageCount === 0 || labelledImages >= imageCount) score += 10;
  if (controls === 0 || labelledControls >= Math.min(controls, 2)) score += 8;
  if (hasSubstantialText) score += 5;

  return {
    id: 'accessibility',
    label: 'Accessibility',
    score: clampScore(score),
    suggestion:
      'Add landmarks, labels, alt text, and visible focus states so the prototype works beyond a mouse-only happy path.',
  };
}

function scoreVisualHierarchy(html) {
  let score = 35;
  const h1 = countMatches(html, RE_H1);
  const headings = countMatches(html, RE_HEADINGS);
  const paragraphs = countMatches(html, RE_PARAGRAPHS);
  const ctas = countMatches(html, RE_CTAS);

  if (h1 === 1) score += 18;
  else if (h1 > 1) score += 8;
  if (headings >= 2) score += 18;
  if (paragraphs >= 2) score += 12;
  if (ctas >= 1) score += 12;
  if (RE_HIERARCHY_KEYWORDS.test(html)) score += 8;
  if (RE_FONT_STYLING.test(html)) score += 7;

  return {
    id: 'visualHierarchy',
    label: 'Visual hierarchy',
    score: clampScore(score),
    suggestion:
      'Clarify the page story with one primary H1, supporting section headings, descriptive body copy, and an obvious primary action.',
  };
}

function scoreSpacing(html) {
  let score = 35;
  const spacingRules = countMatches(html, RE_SPACING);
  const sections = countMatches(html, RE_SECTIONS);

  score += Math.min(28, spacingRules * 4);
  score += Math.min(18, sections * 4);
  if (RE_LAYOUT_KEYWORDS.test(html)) score += 8;
  if (RE_UNITS.test(html)) score += 9;

  return {
    id: 'spacing',
    label: 'Spacing',
    score: clampScore(score),
    suggestion:
      'Use deliberate padding, gaps, max-widths, and section rhythm so the prototype feels composed instead of dumped onto the canvas.',
  };
}

function scoreColorContrast(html) {
  let score = 45;
  const input = String(html || '');

  // Performance optimization: Single pass over input to extract unique hex colors AND perform
  // proximity check for duplicate colors within 80 chars using matchAll iterator.
  const uniqueColors = new Set();
  const lastIndexMap = new Map();
  let hasDuplicateProximity = false;

  for (const match of input.matchAll(RE_HEX_COLOR)) {
    const color = match[0].toLowerCase();
    uniqueColors.add(color);

    if (!hasDuplicateProximity) {
      const prevIndex = lastIndexMap.get(color);
      if (prevIndex !== undefined && match.index - prevIndex <= 80 + color.length) {
        hasDuplicateProximity = true;
      } else {
        lastIndexMap.set(color, match.index);
      }
    }
  }

  const colors = Array.from(uniqueColors);
  const contrastValues = [];

  for (let index = 0; index < colors.length - 1; index += 1) {
    contrastValues.push(contrastRatio(colors[index], colors[index + 1]));
  }

  const usablePairs = contrastValues.filter((value) => value >= 4.5).length;
  const weakPairs = contrastValues.filter((value) => value > 0 && value < 3).length;

  if (colors.length >= 2) score += 12;
  if (usablePairs >= 1) score += 24;
  if (usablePairs >= 2) score += 8;
  if (RE_COLOR_BG.test(input)) score += 8;
  if (RE_BORDER.test(input)) score += 5;
  score -= weakPairs * 18;

  if (hasDuplicateProximity) {
    score -= 20;
  }

  return {
    id: 'colorContrast',
    label: 'Color contrast',
    score: clampScore(score),
    suggestion:
      'Strengthen text/background contrast and avoid same-tone foreground/background pairs, especially around buttons and small copy.',
  };
}

function scoreSemanticHtml(html) {
  let score = 25;
  const semanticTags = countMatches(html, RE_SEMANTIC_TAGS);
  const divs = countMatches(html, RE_DIVS);

  score += Math.min(45, semanticTags * 6);
  if (RE_DOCTYPE.test(html)) score += 8;
  if (RE_TITLE.test(html)) score += 8;
  if (RE_MAIN.test(html)) score += 10;
  if (RE_TYPED_BUTTON.test(html)) score += 5;
  if (semanticTags === 0 && divs > 0) score -= 25;
  if (divs > semanticTags * 3 && divs > 8) score -= 12;

  return {
    id: 'semanticHtml',
    label: 'Semantic HTML',
    score: clampScore(score),
    suggestion:
      'Replace generic div/span structure with header, main, section, nav, lists, labels, and typed buttons where they describe the content.',
  };
}

function gradeForScore(score) {
  if (score >= 85) return 'A';
  if (score >= 70) return 'B';
  if (score >= 55) return 'C';
  return 'D';
}

function scorePrototypeHtml(html = '') {
  const source = String(html || '');
  const hasSubstantialText = hasMinTextLength(source, 81);
  const categories = [
    scoreAccessibility(source, hasSubstantialText),
    scoreVisualHierarchy(source),
    scoreSpacing(source),
    scoreColorContrast(source),
    scoreSemanticHtml(source),
  ];
  const score = clampScore(
    categories.reduce(
      (total, category) => total + category.score * CATEGORY_WEIGHTS[category.id],
      0
    )
  );
  const grade = gradeForScore(score);
  const weakCategories = categories
    .filter((category) => category.score < 70)
    .sort((a, b) => a.score - b.score);
  const suggestions = weakCategories.slice(0, 4).map((category) => ({
    category: category.label,
    text: category.suggestion,
  }));

  return {
    score,
    grade,
    showSuggestions: grade === 'C' || grade === 'D',
    categories,
    suggestions,
  };
}

module.exports = {
  scorePrototypeHtml,
};

function unique(values = []) {
  return Array.from(new Set(values.filter(Boolean)));
}

function extractMatches(source, pattern) {
  return unique(Array.from(String(source || '').matchAll(pattern), (match) => match[1]?.trim()));
}

function inferTokens({ designReference = 'none', designSystemContent = '', prototypeHtml = '' }) {
  const combined = `${designSystemContent}\n${prototypeHtml}`;
  const colors = unique([
    ...extractMatches(combined, /`(#[0-9a-f]{3,8})`/gi),
    ...extractMatches(combined, /(#[0-9a-f]{3,8})\b/gi),
    ...extractMatches(combined, /(rgba?\([^)]+\))/gi),
  ]);
  const typography = unique([
    ...extractMatches(combined, /font-family:\s*([^;]+);/gi),
    ...extractMatches(combined, /fonts?:\s*\[([^\]]+)\]/gi),
  ]);
  const spacing = unique([
    ...extractMatches(combined, /(--[\w-]*spacing[\w-]*):\s*([^;]+);/gi).map((value) =>
      value.split(':').pop()?.trim()
    ),
    ...extractMatches(combined, /\b(\d+(?:\.\d+)?(?:px|rem))\b/gi).filter((value) =>
      /^(4|8|12|16|20|24|28|32|40|48|56|64)(px|rem)$/.test(value)
    ),
  ]);
  const radii = unique([
    ...extractMatches(combined, /border-radius:\s*([^;]+);/gi),
    ...extractMatches(combined, /\b(9999px|\d+(?:\.\d+)?px)\b/gi).filter(
      (value) => value === '9999px' || Number.parseFloat(value) <= 32
    ),
  ]);
  const elevation = unique(extractMatches(combined, /(box-shadow:\s*[^;]+;)/gi));
  const borders = unique(extractMatches(combined, /(border:\s*[^;]+;)/gi));
  const states = unique([
    ...extractMatches(combined, /(hover:[\w-]+)/gi),
    ...extractMatches(combined, /(focus:[\w-]+)/gi),
    ...extractMatches(combined, /(disabled:[\w-]+)/gi),
    ...extractMatches(combined, /(focus state[^.\n]*)/gi),
  ]);

  const unknownTokens = [];
  if (!colors.length) unknownTokens.push('colors');
  if (!typography.length) unknownTokens.push('typography');
  if (!spacing.length) unknownTokens.push('spacing');
  if (!radii.length) unknownTokens.push('radii');
  if (!borders.length && !elevation.length) unknownTokens.push('borders/elevation');
  if (!states.length) unknownTokens.push('component-states');

  return {
    reference: designReference,
    colors,
    typography,
    spacing,
    radii,
    borders,
    elevation,
    states,
    accessibilityNotes: [
      'Use the generated prototype and verification results as the final accessibility source of truth.',
      'Treat any missing token category as a human follow-up rather than inventing values.',
    ],
    rationale: [
      'Derived from the selected design reference content and the actual prototype output where possible.',
      'Prototype values take precedence when they appear in rendered HTML or CSS.',
    ],
    unknownTokens,
  };
}

function yamlList(values = [], indent = '    ') {
  if (!values.length) return `${indent}[]`;
  return values.map((value) => `${indent}- ${JSON.stringify(value)}`).join('\n');
}

function renderDesignMarkdown(tokens) {
  return `# Design package\n\n\`\`\`yaml\nreference: ${JSON.stringify(tokens.reference)}\ntokens:\n  colors:\n${yamlList(tokens.colors)}\n  typography:\n${yamlList(tokens.typography)}\n  spacing:\n${yamlList(tokens.spacing)}\n  radii:\n${yamlList(tokens.radii)}\n  borders:\n${yamlList(tokens.borders)}\n  elevation:\n${yamlList(tokens.elevation)}\n  states:\n${yamlList(tokens.states)}\naccessibilityNotes:\n${yamlList(tokens.accessibilityNotes, '  ')}\nunknownTokens:\n${yamlList(tokens.unknownTokens, '  ')}\n\`\`\`\n\n## Rationale\n\n${tokens.rationale.map((line) => `- ${line}`).join('\n')}\n`;
}

function renderTokenSection(title, values, renderValue) {
  if (!values.length) {
    return `<section><h2>${title}</h2><p>No reliable values were inferred for this category.</p></section>`;
  }
  return `<section><h2>${title}</h2><div class="token-grid">${values.map(renderValue).join('')}</div></section>`;
}

function renderDesignHtml(tokens) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Design package</title>
  <style>
    :root { color-scheme: dark; font-family: Inter, system-ui, sans-serif; }
    body { margin: 0; background: #0d0f14; color: #f5f0e8; padding: 32px; }
    h1, h2 { margin: 0 0 12px; }
    p, li { color: rgba(245,240,232,0.75); line-height: 1.55; }
    section { margin-top: 28px; padding: 20px; border: 1px solid rgba(255,255,255,0.12); border-radius: 18px; background: rgba(255,255,255,0.03); }
    .token-grid { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
    .token-card { border: 1px solid rgba(255,255,255,0.1); border-radius: 14px; padding: 14px; background: rgba(0,0,0,0.18); }
    .swatch { height: 48px; border-radius: 10px; border: 1px solid rgba(255,255,255,0.12); margin-bottom: 10px; }
    code { color: #c1ff00; }
  </style>
</head>
<body>
  <h1>Design package</h1>
  <p>Reference: <code>${tokens.reference}</code></p>
  ${renderTokenSection('Colors', tokens.colors, (value) => `<div class="token-card"><div class="swatch" style="background:${value};"></div><code>${value}</code></div>`)}
  ${renderTokenSection('Typography', tokens.typography, (value) => `<div class="token-card"><strong style="font-family:${value};">Sample Aa</strong><br /><code>${value}</code></div>`)}
  ${renderTokenSection('Spacing', tokens.spacing, (value) => `<div class="token-card"><strong>${value}</strong><br /><code>${value}</code></div>`)}
  ${renderTokenSection('Radii', tokens.radii, (value) => `<div class="token-card"><div class="swatch" style="background:rgba(193,255,0,0.16);border-radius:${value};"></div><code>${value}</code></div>`)}
  ${renderTokenSection('Borders', tokens.borders, (value) => `<div class="token-card"><code>${value}</code></div>`)}
  ${renderTokenSection('Elevation', tokens.elevation, (value) => `<div class="token-card"><code>${value}</code></div>`)}
  ${renderTokenSection('Component states', tokens.states, (value) => `<div class="token-card"><code>${value}</code></div>`)}
  <section>
    <h2>Accessibility notes</h2>
    <ul>${tokens.accessibilityNotes.map((note) => `<li>${note}</li>`).join('')}</ul>
  </section>
  <section>
    <h2>Unknown tokens</h2>
    <ul>${(tokens.unknownTokens.length ? tokens.unknownTokens : ['None']).map((token) => `<li>${token}</li>`).join('')}</ul>
  </section>
</body>
</html>`;
}

function buildDesignPackage({
  designReference = 'none',
  designSystemContent = '',
  prototypeHtml = '',
}) {
  const tokens = inferTokens({ designReference, designSystemContent, prototypeHtml });
  return {
    tokens,
    markdown: renderDesignMarkdown(tokens),
    html: renderDesignHtml(tokens),
  };
}

module.exports = {
  buildDesignPackage,
};

/**
 * routes/build-agents.js
 * Public interfaces:
 * - GET /api/build-agents: detect available BYOK build-agent CLIs.
 * - POST /api/build-agents/run: create a handoff package and optionally launch a detected CLI.
 */

const fs = require('fs');
const path = require('path');
const { createHandoffPackage, getAgentScope } = require('../lib/handoff-package');
const { detectBuildAgents, launchBuildAgent } = require('../lib/build-agents');

function uniqueAgentIds(agentIds = [], fallbackAgentId = 'handoff') {
  const raw = Array.isArray(agentIds) ? agentIds : [fallbackAgentId];
  const seen = new Set();
  return raw
    .map((id) => String(id || '').trim())
    .filter(Boolean)
    .filter((id) => {
      if (seen.has(id)) return false;
      seen.add(id);
      return true;
    })
    .slice(0, 5);
}

function scopedProjectName(projectName, agent) {
  return `${projectName} — ${agent.name || agent.id}`;
}

function buildRootManifest({
  safeName,
  projectName,
  cauldronVersion,
  projectType,
  templateId,
  designReference,
  sessionId,
  agents,
  packages,
  verification = null,
}) {
  return {
    schemaVersion: 1,
    projectName: safeName,
    displayName: projectName,
    createdAt: new Date().toISOString(),
    source: 'cauldron-os',
    cauldronVersion,
    projectType,
    templateId,
    designReference: designReference || 'none',
    sessionId: sessionId || null,
    verification,
    orchestration: {
      mode: 'multi-agent',
      agents: agents.map((agent) => ({
        id: agent.id,
        name: agent.name,
        available: agent.available,
        scope: getAgentScope(agent.id),
      })),
      packages: packages.map((pkg) => ({
        agentId: pkg.agentId,
        agentName: pkg.agentName,
        mode: pkg.mode,
        relativePath: pkg.relativePath,
        manifestPath: pkg.manifestPath,
        command: pkg.command || null,
        error: pkg.error || null,
      })),
    },
  };
}

function registerBuildAgentRoutes(app, deps) {
  const { db, workspace, ensureDesignSystem, safeProjectName, getProjectsDir, PACKAGE_VERSION } =
    deps;

  app.get('/api/build-agents', (req, res) => {
    res.json({ success: true, agents: detectBuildAgents() });
  });

  app.post('/api/build-agents/run', async (req, res) => {
    const {
      projectName,
      agentId = 'handoff',
      blueprint = '',
      prototypeHtml = '',
      designReference = 'none',
      templateId = '',
      projectType = 'app',
      sessionId = '',
      dryRun = false,
      bootstrap = false,
      agentIds = [],
      verification = null,
      includeDesignPackage = false,
    } = req.body || {};

    if (!projectName || (!blueprint && !sessionId)) {
      return res
        .status(400)
        .json({ success: false, error: 'projectName and either blueprint or sessionId required' });
    }

    const safeName = safeProjectName(projectName);
    const projectPath = path.join(getProjectsDir(), safeName);

    if (fs.existsSync(projectPath)) {
      return res
        .status(409)
        .json({ success: false, error: `Project "${safeName}" already exists` });
    }

    try {
      const designSystemContent = await ensureDesignSystem(designReference);
      const selectedAgentIds = uniqueAgentIds(agentIds, agentId);
      const isMultiAgent = selectedAgentIds.length > 1;

      if (isMultiAgent) {
        fs.mkdirSync(path.join(projectPath, 'agents'), { recursive: true });
        const detectedAgents = detectBuildAgents();
        const selectedAgents = selectedAgentIds.map(
          (id) =>
            detectedAgents.find((agent) => agent.id === id) || {
              id,
              name: id,
              available: false,
              command: null,
              launch: 'run-prompt',
              notes: `${id} not detected`,
            }
        );
        const orchestration = { mode: 'multi-agent', agents: selectedAgents };
        const agentResults = [];

        for (const agent of selectedAgents) {
          const relativePath = path.join('agents', agent.id);
          const agentProjectPath = path.join(projectPath, relativePath);
          const handoff = await createHandoffPackage({
            projectPath: agentProjectPath,
            projectName: scopedProjectName(projectName, agent),
            safeName: `${safeName}-${agent.id}`,
            cauldronVersion: PACKAGE_VERSION,
            blueprint,
            prototypeHtml,
            designReference,
            designSystemContent,
            templateId,
            projectType,
            sessionId,
            workspace,
            agentId: agent.id,
            agentScope: getAgentScope(agent.id),
            orchestration,
            bootstrap: Boolean(bootstrap),
            verification,
            includeDesignPackage,
          });

          const launch = launchBuildAgent({
            agentId: agent.id,
            projectPath: agentProjectPath,
            dryRun,
          });
          handoff.manifest.agent = {
            ...handoff.manifest.agent,
            mode: launch.mode,
            requestedCli: launch.agent.id === 'handoff' ? null : launch.agent.id,
            command: launch.command,
            scope: getAgentScope(agent.id),
          };
          fs.writeFileSync(
            handoff.manifestPath,
            JSON.stringify(handoff.manifest, null, 2) + '\n',
            'utf8'
          );

          agentResults.push({
            success: true,
            mode: launch.mode,
            agentId: launch.agent.id,
            agentName: launch.agent.name,
            scope: getAgentScope(agent.id),
            fallback: Boolean(launch.fallback),
            dryRun: Boolean(launch.dryRun),
            error: launch.error || null,
            pid: launch.pid || null,
            projectPath: agentProjectPath,
            relativePath,
            manifestPath: handoff.manifestPath,
            command: launch.command,
            logPath: launch.logPath || null,
            files: handoff.files,
            filesCopied: handoff.filesCopied,
            bootstrap: handoff.bootstrap || null,
          });
        }

        const rootManifest = buildRootManifest({
          safeName,
          projectName,
          cauldronVersion: PACKAGE_VERSION,
          projectType,
          templateId,
          designReference,
          sessionId,
          agents: selectedAgents,
          packages: agentResults,
          verification,
        });
        const manifestPath = path.join(projectPath, 'cauldron.project.json');
        fs.writeFileSync(manifestPath, JSON.stringify(rootManifest, null, 2) + '\n', 'utf8');

        try {
          db.setProjectStatusOverride(
            safeName,
            'needs_review',
            `Multi-agent handoff created for ${selectedAgents.length} agents`
          );
        } catch (statusErr) {
          console.warn('[Cauldron] Status override warning:', statusErr.message);
        }

        let draftId = null;
        try {
          const draft = db.createDraft({
            projectName: safeName,
            brainDump: sessionId
              ? `Multi-agent build session: ${sessionId}`
              : `Multi-agent handoff: ${selectedAgents.map((agent) => agent.name).join(', ')}`,
            blueprint: blueprint || '',
            designReference: designReference || 'handoff',
            generationMode: 'multi-agent-handoff',
            modelUsed: selectedAgents.map((agent) => agent.name).join(', '),
          });
          draftId = draft.id;
        } catch (recordErr) {
          console.warn('[Cauldron] Multi-agent record warning:', recordErr.message);
        }

        return res.json({
          success: true,
          mode: 'multi-agent',
          agentId: 'multi',
          agentName: 'Multi-agent handoff',
          fallback: agentResults.some((result) => result.fallback),
          dryRun: Boolean(dryRun),
          projectPath,
          manifestPath,
          draftId,
          agentResults,
          agents: selectedAgents.map((agent) => ({
            id: agent.id,
            name: agent.name,
            available: agent.available,
            scope: getAgentScope(agent.id),
          })),
          verification,
        });
      }

      const shouldBootstrap = Boolean(req.body.bootstrap);
      const handoff = await createHandoffPackage({
        projectPath,
        projectName,
        safeName,
        cauldronVersion: PACKAGE_VERSION,
        blueprint,
        prototypeHtml,
        designReference,
        designSystemContent,
        templateId,
        projectType,
        sessionId,
        workspace,
        agentId,
        bootstrap: shouldBootstrap,
        verification,
        includeDesignPackage,
      });

      const launch = launchBuildAgent({ agentId, projectPath, dryRun });
      if (launch.command) {
        handoff.manifest.agent = {
          mode: launch.mode,
          requestedCli: launch.agent.id,
          command: launch.command,
        };
        fs.writeFileSync(
          handoff.manifestPath,
          JSON.stringify(handoff.manifest, null, 2) + '\n',
          'utf8'
        );
      }

      try {
        db.setProjectStatusOverride(
          safeName,
          launch.launched ? 'building' : 'needs_review',
          launch.launched ? `Launched ${launch.agent.name}` : 'Handoff package created'
        );
      } catch (statusErr) {
        console.warn('[Cauldron] Status override warning:', statusErr.message);
      }

      let draftId = null;
      try {
        const draft = db.createDraft({
          projectName: safeName,
          brainDump: sessionId ? `Build session: ${sessionId}` : '',
          blueprint: handoff.blueprint || '',
          designReference: designReference || 'handoff',
          generationMode: launch.launched ? `agent-${launch.agent.id}` : 'handoff',
          modelUsed: launch.agent?.name || 'handoff',
        });
        draftId = draft.id;
      } catch (recordErr) {
        console.warn('[Cauldron] Build agent record warning:', recordErr.message);
      }

      res.json({
        success: true,
        mode: launch.mode,
        agentId: launch.agent.id,
        agentName: launch.agent.name,
        fallback: Boolean(launch.fallback),
        dryRun: Boolean(launch.dryRun),
        error: launch.error || null,
        pid: launch.pid || null,
        projectPath,
        manifestPath: handoff.manifestPath,
        command: launch.command,
        logPath: launch.logPath || null,
        draftId,
        files: handoff.files,
        filesCopied: handoff.filesCopied,
        bootstrap: handoff.bootstrap || null,
        verification: handoff.manifest.verification || null,
      });
    } catch (err) {
      console.error('[Cauldron] Build agent run error:', err);
      res
        .status(500)
        .json({ success: false, error: 'Build agent handoff failed', details: err.message });
    }
  });
}

module.exports = registerBuildAgentRoutes;

/**
 * routes/build.js
 * Public interfaces:
 * - POST /api/build/start: create an isolated build workspace.
 * - POST /api/build/generate: SSE XML-tool build execution.
 * - POST /api/build/refine: SSE continuation for an existing workspace.
 * - POST /api/build/stop: abort active build execution.
 * - GET /api/build/files/:sessionId: list workspace files.
 * - GET /api/build/file/:sessionId: read a workspace file by query path.
 * - GET /api/build/status/:sessionId: inspect build session state.
 */

const path = require('path');
const { runVerification } = require('../lib/verification');
const { isInsideRoot, parseSessionId } = require('../lib/path-safety');

function errorStatus(err, fallback = 500) {
  if (err.statusCode) return err.statusCode;
  if (err.code === 'ESECURITY' || err.code === 'EINVAL_SESSION' || err.code === 'EINVAL_PATH') {
    return 400;
  }
  return fallback;
}

function requireRequestSessionId(value) {
  const sessionId = parseSessionId(value);
  if (!sessionId) {
    const err = new Error('Invalid sessionId');
    err.statusCode = 400;
    throw err;
  }
  return sessionId;
}

function registerBuildRoutes(app, deps) {
  const {
    db,
    workspace,
    activeBuildControllers,
    buildSessions,
    getProjectsDir,
    buildSystemPrompt,
    _runCloudAgentBuild,
    generateWithTools,
  } = deps;

  function resolveVerificationTarget({ sessionId = '', projectPath = '' }) {
    if (sessionId) {
      const sanitized = requireRequestSessionId(sessionId);
      return {
        targetDir: workspace.workspaceDir(sanitized),
        targetType: 'workspace',
        sessionId: sanitized,
      };
    }

    if (projectPath) {
      const root = path.resolve(getProjectsDir());
      const resolved = path.resolve(projectPath);
      if (!isInsideRoot(root, resolved)) {
        throw new Error('Invalid projectPath');
      }
      return {
        targetDir: resolved,
        targetType: 'project',
        sessionId: '',
      };
    }

    throw new Error('sessionId or projectPath required');
  }

  app.post('/api/build/start', async (req, res) => {
    try {
      const { prompt, model, sessionId, designReference, templateId, projectType } = req.body;
      const sid = sessionId ? requireRequestSessionId(sessionId) : db.generateSessionId();
      const wsDir = await workspace.ensureWorkspace(sid);

      buildSessions.set(sid, {
        sessionId: sid,
        prompt: prompt || '',
        model: model || 'llama3.2',
        designReference: designReference || 'none',
        templateId: templateId || '',
        projectType: projectType || 'app',
        workspaceDir: wsDir,
        startedAt: new Date().toISOString(),
        actions: [],
        files: [],
        status: 'initialized',
      });

      res.json({ success: true, sessionId: sid, workspaceDir: wsDir });
    } catch (err) {
      console.error('[Build] Start error:', err);
      res.status(err.statusCode || 500).json({ success: false, error: err.message });
    }
  });

  app.post('/api/build/generate', async (req, res) => {
    const {
      prompt,
      model,
      sessionId,
      systemPrompt,
      apiKey,
      cloudModel,
      baseUrl,
      base_url,
      verify = false,
      templateId = '',
    } = req.body;
    let sid;
    try {
      sid = requireRequestSessionId(sessionId);
    } catch (err) {
      return res.status(400).json({ error: err.message });
    }

    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    });

    const startTime = Date.now();
    const isCloud = ['openai', 'gemini'].includes(model);
    const controller = new AbortController();
    activeBuildControllers.set(sid, controller);

    try {
      await workspace.ensureWorkspace(sid);
      const sysPrompt = systemPrompt || (await buildSystemPrompt({ sessionId: sid }));

      const sendEvent = (event, data) => {
        if (!controller.signal.aborted) {
          try {
            res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
          } catch {}
        }
      };

      let finalFiles = [];
      let finalActions = [];

      if (isCloud) {
        if (!apiKey) {
          sendEvent('error', { message: `API key required for ${model}` });
          return res.end();
        }
        const result = await _runCloudAgentBuild({
          prompt,
          model,
          apiKey,
          systemPrompt: sysPrompt,
          sessionId: sid,
          onToken: (text) => sendEvent('token', { text }),
          signal: controller.signal,
          cloudModel,
          baseUrl: baseUrl || base_url,
        });
        finalFiles = result.files || [];
        finalActions = result.actions || [];
        for (const action of finalActions) {
          sendEvent('action', { tool: action.name, path: action.args?.path, status: 'start' });
          sendEvent('result', {
            tool: action.name,
            path: action.args?.path,
            status: 'complete',
            output: action.result,
          });
          if (
            action.args &&
            action.args.path &&
            ['write_file', 'edit_file', 'delete_file'].includes(action.name)
          ) {
            sendEvent('filechange', { path: action.args.path });
          }
        }
      } else {
        const agentGen = generateWithTools({
          prompt,
          model,
          systemPrompt: sysPrompt,
          sessionId: sid,
          onStream: (chunk) => {
            if (chunk && chunk.token) sendEvent('token', { text: chunk.token });
          },
          onAction: ({ action, args, result }) => {
            sendEvent('action', { tool: action, path: args?.path, status: 'start' });
            sendEvent('result', {
              tool: action,
              path: args?.path,
              status: 'complete',
              output: result,
            });
          },
          onFileChange: ({ path }) => {
            sendEvent('filechange', { path });
          },
        });
        for await (const chunk of agentGen) {
          if (controller.signal.aborted) break;
          if (chunk.done) {
            finalFiles = chunk.files || [];
            finalActions = chunk.actions || [];
          }
        }
      }

      if (!controller.signal.aborted) {
        const duration = Date.now() - startTime;
        const nextSession = {
          ...(buildSessions.get(sid) || {}),
          sessionId: sid,
          status: 'completed',
          completedAt: new Date().toISOString(),
          files: finalFiles,
          actions: finalActions,
          duration,
        };
        buildSessions.set(sid, nextSession);

        let draftId = null;
        try {
          const draftRecord = db.createDraft({
            projectName: `build-${sid.slice(0, 8)}`,
            brainDump: prompt,
            blueprint: JSON.stringify({ files: finalFiles, actions: finalActions }),
            designReference: 'build',
            generationMode: 'build',
            modelUsed: model,
          });
          draftId = draftRecord.id;
        } catch (error) {
          console.warn('[Build] Draft save warning:', error.message);
        }

        let verification = null;
        if (verify) {
          verification = await runVerification({
            targetDir: workspace.workspaceDir(sid),
            options: { targetType: 'workspace', templateId },
          });
          buildSessions.set(sid, {
            ...nextSession,
            verification,
          });
          sendEvent('verification', verification);
        }

        sendEvent('done', {
          files: finalFiles,
          actions: finalActions,
          duration,
          draftId,
          verification,
        });
      }
      res.end();
    } catch (err) {
      console.error('[Build] Generate error:', err);
      try {
        res.write(`event: error\ndata: ${JSON.stringify({ message: err.message })}\n\n`);
        res.end();
      } catch {}
    } finally {
      activeBuildControllers.delete(sid);
    }
  });

  app.post('/api/build/refine', async (req, res) => {
    const {
      prompt,
      sessionId,
      systemPrompt,
      model,
      apiKey,
      cloudModel,
      baseUrl,
      base_url,
      verify = false,
      templateId = '',
    } = req.body;
    let sid;
    try {
      sid = requireRequestSessionId(sessionId);
    } catch (err) {
      return res.status(400).json({ error: err.message });
    }

    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    });

    const startTime = Date.now();
    const isCloud = ['openai', 'gemini'].includes(model);
    const controller = new AbortController();
    activeBuildControllers.set(sid, controller);

    try {
      await workspace.ensureWorkspace(sid);
      const sysPrompt = systemPrompt || (await buildSystemPrompt({ sessionId: sid }));

      const sendEvent = (event, data) => {
        if (!controller.signal.aborted) {
          try {
            res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
          } catch {}
        }
      };

      let finalFiles = [];
      let finalActions = [];

      if (isCloud) {
        if (!apiKey) {
          sendEvent('error', { message: `API key required for ${model}` });
          return res.end();
        }
        const result = await _runCloudAgentBuild({
          prompt,
          model,
          apiKey,
          systemPrompt: sysPrompt,
          sessionId: sid,
          onToken: (text) => sendEvent('token', { text }),
          signal: controller.signal,
          cloudModel,
          baseUrl: baseUrl || base_url,
        });
        finalFiles = result.files || [];
        finalActions = result.actions || [];
        for (const action of finalActions) {
          sendEvent('action', { tool: action.name, path: action.args?.path, status: 'start' });
          sendEvent('result', {
            tool: action.name,
            path: action.args?.path,
            status: 'complete',
            output: action.result,
          });
          if (
            action.args &&
            action.args.path &&
            ['write_file', 'edit_file', 'delete_file'].includes(action.name)
          ) {
            sendEvent('filechange', { path: action.args.path });
          }
        }
      } else {
        const agentGen = generateWithTools({
          prompt,
          model: model || 'llama3.2',
          systemPrompt: sysPrompt,
          sessionId: sid,
          onStream: (chunk) => {
            if (chunk && chunk.token) sendEvent('token', { text: chunk.token });
          },
          onAction: ({ action, args, result }) => {
            sendEvent('action', { tool: action, path: args?.path, status: 'start' });
            sendEvent('result', {
              tool: action,
              path: args?.path,
              status: 'complete',
              output: result,
            });
          },
          onFileChange: ({ path }) => {
            sendEvent('filechange', { path });
          },
        });
        for await (const chunk of agentGen) {
          if (controller.signal.aborted) break;
          if (chunk.done) {
            finalFiles = chunk.files || [];
            finalActions = chunk.actions || [];
          }
        }
      }

      if (!controller.signal.aborted) {
        const duration = Date.now() - startTime;
        const existingSession = buildSessions.get(sid) || {};
        const mergedFiles = [...new Set([...(existingSession.files || []), ...finalFiles])];
        const mergedActions = [...(existingSession.actions || []), ...finalActions];
        const nextSession = {
          ...existingSession,
          status: 'refined',
          completedAt: new Date().toISOString(),
          files: mergedFiles,
          actions: mergedActions,
          duration: (existingSession.duration || 0) + duration,
        };
        buildSessions.set(sid, nextSession);

        let verification = null;
        if (verify) {
          verification = await runVerification({
            targetDir: workspace.workspaceDir(sid),
            options: { targetType: 'workspace', templateId },
          });
          buildSessions.set(sid, {
            ...nextSession,
            verification,
          });
          sendEvent('verification', verification);
        }
        sendEvent('done', { files: mergedFiles, actions: mergedActions, duration, verification });
      }
      res.end();
    } catch (err) {
      console.error('[Build] Refine error:', err);
      try {
        res.write(`event: error\ndata: ${JSON.stringify({ message: err.message })}\n\n`);
        res.end();
      } catch {}
    } finally {
      activeBuildControllers.delete(sid);
    }
  });

  app.post('/api/build/stop', (req, res) => {
    try {
      const { sessionId } = req.body;
      const sid = requireRequestSessionId(sessionId);
      const controller = activeBuildControllers.get(sid);
      if (controller) {
        controller.abort();
        activeBuildControllers.delete(sid);
      }
      const session = buildSessions.get(sid);
      if (session) session.status = 'stopped';
      res.json({ success: true });
    } catch (err) {
      console.error('[Build] Stop error:', err);
      res.status(err.statusCode || 500).json({ success: false, error: err.message });
    }
  });

  app.get('/api/build/files/:sessionId', async (req, res) => {
    try {
      const sanitized = requireRequestSessionId(req.params.sessionId);
      const files = await workspace.wsListFiles(sanitized);
      res.json({ success: true, files });
    } catch (err) {
      console.error('[Build] List files error:', err);
      res.status(errorStatus(err)).json({
        success: false,
        error: err.message,
      });
    }
  });

  app.get('/api/build/file/:sessionId', async (req, res) => {
    try {
      const filePath = req.query.path;
      if (!filePath)
        return res.status(400).json({ success: false, error: 'path query parameter required' });
      const sanitized = requireRequestSessionId(req.params.sessionId);
      const content = await workspace.wsReadFile(sanitized, filePath);
      res.json({ success: true, content });
    } catch (err) {
      if (err.code === 'ENOENT')
        return res.status(404).json({ success: false, error: 'File not found' });
      console.error('[Build] Read file error:', err);
      res.status(errorStatus(err)).json({ success: false, error: err.message });
    }
  });

  app.get('/api/build/status/:sessionId', async (req, res) => {
    try {
      const sanitized = requireRequestSessionId(req.params.sessionId);
      const files = await workspace.wsListFiles(sanitized);
      const fileCount = files.filter((f) => f.type === 'file').length;
      const totalSize = files.filter((f) => f.type === 'file').reduce((sum, f) => sum + f.size, 0);
      const sessionData = buildSessions.get(sanitized) || {};
      res.json({
        success: true,
        status: {
          sessionId: sanitized,
          fileCount,
          totalSize,
          lastAction: sessionData.actions
            ? sessionData.actions[sessionData.actions.length - 1] || null
            : null,
          duration: sessionData.duration || null,
          status: sessionData.status || 'unknown',
          startedAt: sessionData.startedAt || null,
          completedAt: sessionData.completedAt || null,
          verification: sessionData.verification || null,
          files,
        },
      });
    } catch (err) {
      console.error('[Build] Status error:', err);
      res.status(errorStatus(err)).json({ success: false, error: err.message });
    }
  });

  app.post('/api/build/verify', async (req, res) => {
    try {
      const { sessionId = '', projectPath = '', templateId = '' } = req.body || {};
      const target = resolveVerificationTarget({ sessionId, projectPath });
      const verification = await runVerification({
        targetDir: target.targetDir,
        options: {
          targetType: target.targetType,
          templateId,
        },
      });

      if (target.sessionId) {
        buildSessions.set(target.sessionId, {
          ...(buildSessions.get(target.sessionId) || {}),
          sessionId: target.sessionId,
          verification,
        });
      }

      res.json({ success: true, verification });
    } catch (err) {
      console.error('[Build] Verify error:', err);
      res.status(errorStatus(err)).json({ success: false, error: err.message });
    }
  });
}

module.exports = registerBuildRoutes;
